SELECT COUNT(*) FROM (
  SELECT i.InvoiceId
  FROM Invoice i JOIN InvoiceLine l ON l.InvoiceId = i.InvoiceId
  GROUP BY i.InvoiceId
  HAVING ABS(i.Total - SUM(l.UnitPrice * l.Quantity)) > 0.005
);

SELECT COUNT(*) FROM (
  SELECT City FROM Customer
  GROUP BY City
  HAVING COUNT(*) > 1
);

SELECT a.name, COUNT(*) AS n
FROM songs s JOIN artists a ON a.id = s.artist_id
GROUP BY a.name ORDER BY n DESC LIMIT 1;

SELECT COUNT(*) FROM (
  SELECT movie_id FROM stars
  GROUP BY movie_id
  HAVING COUNT(*) = 1
);

SELECT COUNT(*) FROM (
  SELECT title FROM movies
  GROUP BY title
  HAVING COUNT(*) > 1
);

SELECT COUNT(*) FROM (
  SELECT movie_id FROM directors
  GROUP BY movie_id
  HAVING COUNT(*) > 1
);

SELECT COUNT(*) FROM courthouse_security_logs
WHERE year = 2020 AND month = 7 AND day = 28 AND hour = 10
  AND minute BETWEEN 15 AND 25 AND activity = 'exit';

SELECT COUNT(*), SUM(amount) FROM atm_transactions
WHERE year = 2020 AND month = 7 AND day = 28
  AND atm_location = 'Fifer Street' AND transaction_type = 'withdraw';

SELECT COUNT(*) FROM (
  SELECT FullName FROM pcards
  GROUP BY FullName
  HAVING COUNT(*) > 10
);

SELECT COUNT(*) FROM (
  SELECT FullName FROM pcards
  GROUP BY FullName
  HAVING COUNT(DISTINCT Vendor) > 100
);

SELECT COUNT(*) FROM (
  SELECT FullName, Month FROM pcards
  GROUP BY FullName, Month
  HAVING SUM(Amount) > 10000
);

SELECT SUM(Amount BETWEEN 4900 AND 4999.99) AS Just_below,
       SUM(Amount BETWEEN 4800 AND 4899.99) AS Band_below
FROM pcards;

SELECT COUNT(*) FROM (
  SELECT FullName, Vendor, TransactionDate
  FROM pcards
  GROUP BY FullName, Vendor, TransactionDate
  HAVING COUNT(*) > 1 AND SUM(Amount) > 5000
);
